import json, sys
f='/root/.claude/projects/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d.jsonl'
want=('2026-10-25T19:06:08','2026-10-26T04:28:41','2026-10-26T04:47:50','2026-10-26T05:25:27','2026-10-26T07:30:36','2026-10-26T07:36:39','2026-10-26T07:42:15','2026-10-26T07:46:17','2026-10-26T07:48:49')
found={}
with open(f,encoding='utf-8',errors='replace') as fh:
    for line in fh:
        if '"type":"user"' not in line[:400] and '"type": "user"' not in line[:400]:
            continue
        ts_i=line.find('"timestamp"')
        if ts_i<0: continue
        ts=line[ts_i+13:ts_i+13+19]
        if ts not in want: continue
        try:
            d=json.loads(line)
        except Exception:
            continue
        if (d.get('origin') or {}).get('kind')!='human': continue
        m=d.get('message',{})
        c=m.get('content')
        if isinstance(c,list):
            c=' '.join(x.get('text','') for x in c if isinstance(x,dict))
        found[ts]=(d.get('timestamp'),c)
for ts in want:
    if ts in found:
        t,c=found[ts]
        print('###',t); print(c[:1400].replace('\n',' ')); print()
    else:
        print('###',ts,'NOT FOUND as human message')
EOF

